    for i in range(len(values)):
        prefix_sum[i + 1] = prefix_sum[i] + values[i]

    # Compute the sum for each query using the prefix sum array
    results = []
    for start, end in queries:
        results.append(prefix_sum[end + 1] - prefix_sum[start])
    return results

